	informer := db.settingsMgr.GetClusterInformer()
	servers, err := informer.GetClusterServersByName(name)
	if err != nil {
		return nil, err
	}

	// Lazily evaluate whether in-cluster is enabled. The settings manager (which
	// requires the argocd-cm ConfigMap) is only consulted when the requested name
	// is the reserved in-cluster cluster name. For all other names this lets the
	// lookup succeed even when argocd-cm is absent.
	if name == appv1.KubernetesInClusterName {
		argoSettings, err := db.settingsMgr.GetSettings()
		if err != nil {
			return nil, err
		}

		// Handle local cluster special case
		if len(servers) == 0 && argoSettings.InClusterEnabled {
			return []string{appv1.KubernetesInternalAPIServerAddr}, nil
		}

		// Filter out disabled in-cluster
		if !argoSettings.InClusterEnabled {
			filtered := make([]string, 0, len(servers))
			for _, s := range servers {
				if s != appv1.KubernetesInternalAPIServerAddr {
					filtered = append(filtered, s)
				}
			}
			return filtered, nil
		}
